import { HERO_LOGO_SVG } from "@/lib/hero-logo-svg.generated";

/**
 * The hero's logo: TREFF ● PUNKT (logo-compact-inverse.svg — light letters for
 * the photo, no cast shadow), inlined so the page CSS can pulse the dot
 * (`.hero-logo .tpof-dot` in globals.css) while the letters stay still.
 * The markup is a byte copy of the file, generated by
 * scripts/gen-hero-logo.mjs — never edited here.
 *
 * Decorative: the header already carries the logo link with its name, so this
 * copy is aria-hidden and not announced twice.
 */
export function HeroLogo({ className }: { className?: string }) {
  return (
    <div
      className={className ? `hero-logo ${className}` : "hero-logo"}
      aria-hidden="true"
      dangerouslySetInnerHTML={{ __html: HERO_LOGO_SVG }}
    />
  );
}
